def lcs_py(a, b):
    if len(a) < len(b):
        a, b = b, a
    n = len(b)
    if n == 0:
        return 0
    mask = (1 << n) - 1
    pm = {}
    bit = 1
    for c in b:
        pm[c] = pm.get(c, 0) | bit
        bit <<= 1
    pairs = {c: (m, mask ^ m) for c, m in pm.items()}
    V = mask
    get = pairs.get
    for p in map(get, a):
        if p is None:
            continue
        M, NM = p
        V = (V + (V & M)) | (V & NM)
    return n - (V & mask).bit_count()

def lcs(a, b):
